function attributeDrop(results) {
  // results: {oldHarness_newModel, newHarness_oldModel} pass booleans
  const r = results;
  if (!r.oldHarness_newModel && r.newHarness_oldModel) return 'MODEL DRIFT';
  if (r.oldHarness_newModel && !r.newHarness_oldModel) return 'HARNESS REGRESSION';
  if (!r.oldHarness_newModel && !r.newHarness_oldModel) return 'INTERACTION-or-flaky';
  return 'no-drop';
}
console.log(attributeDrop({ oldHarness_newModel: false, newHarness_oldModel: true }));
console.log(attributeDrop({ oldHarness_newModel: true, newHarness_oldModel: false }));
console.log(attributeDrop({ oldHarness_newModel: true, newHarness_oldModel: true }));

